INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-f98b3ae60b16','lushan-platform-2026-07','庐山抗战历史事件表（批注地点坐标）.docx','docx',NULL,117,'row-117','{"cells":["4.3","","庐山管理局令警察署清查全山避难居民并制作下山通行证⑦","庐山"]}'::jsonb,'751021d3983af5100b059ea67ea3bb67bea9ae5e3a631ec6449c02e0a4ea2791');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-6863aee6123a','lushan-platform-2026-07','庐山抗战历史事件表（批注地点坐标）.docx','docx',NULL,118,'row-118','{"cells":["4.15-4.17","","日军从南昌、武汉抽调矶谷大阪101等三个师团⑥/冈吉106师团、太久保联队，分大寨、莲花峰、好汉坡、月弓堑、土坝岭、铁船峰、十里铺、白衣宫八路进攻庐山。守军三团一大队对付从莲花洞、龙门沟上来的佐藤联队；二大队对付从剪刀峡、土坝岭、锦谷上来的太久保联队；三大队对付从铁船峰、碧云庵、报国寺上来的佐泽联队。十一团四大队对付从小天池、女儿城进犯的冈吉联队；五大队对付从三叠泉、五老峰进犯的铃木联队；六大队对付从筲箕洼、仰天坪进犯的山口联队。⑯","大寨、莲花峰、好汉坡、月弓堑、土坝岭、铁船峰、十里铺、白衣宫"]}'::jsonb,'5ed82e4b63fa9c877cede091466c4e6572a11517af78d29fed625d5862d7563d');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-1b9202af02c8','lushan-platform-2026-07','庐山抗战历史事件表（批注地点坐标）.docx','docx',NULL,119,'row-119','{"cells":["4.17","","日军从大寨、好汉坡、东林寺、大天池、三叠泉、息肩亭各线围攻。 日军一联队从九莲公路和尚坟（东林寺附近）分四路进攻牯岭，联队长在土坝岭被击毙，晚占领小天池。一部日军在汉奸引路下从莲花洞小路向牯岭攻击⑥","九莲公路和尚坟、土坝岭、小天池"]}'::jsonb,'5059fde8347156bf11ae8fb9319a20fefb1b761f1b3849c4a7d0ffdbd12ca193');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-8aa1ddb4ed26','lushan-platform-2026-07','庐山抗战历史事件表（批注地点坐标）.docx','docx',NULL,120,'row-120','{"cells":["4.18-4.20","","牯岭被完全包围，副总指挥部退守仰天坪，余部困守太乙村、五老峰，多牺牲。在汉奸引路下的一部日军从王家坡、碧龙潭登上小天池阵地，进而攻入牯岭，月弓堑、剪刀峡、土坝岭防线也被攻破，庐山沦陷。⑥ 游击队副总指挥部三团、警察局突围下山，从碧云庵经报国垄、越南浔铁路于20日夜进入岷山，十一团从张家山下山。⑥","仰天坪、太乙村、五老峰、张家山、碧云庵"]}'::jsonb,'80184e598501d874d581dec06419ec0998e544aa0b285042722b66ae42819781');
