INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-933718b78033','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',9,'row-9','{"档案来源":"庐山历史纪事3","页数":"40-44","档案原文":null,"档案内容简介":"1、杨遇春从汉口前往第三战区，学长管商请他担任副总指挥并负责庐山游击根据地；\n2、杨将军通过隘口小路在19270811上山；\n3、庐山货币、武器与粮食、衣物等物资情况与获取来源   日军的空袭；\n4、庐山山上居民疏散与老九会；\n5、交通线附近的突袭和骚扰；\n6、与汉奸关系的处理与后续情报供给（南昌失陷和赣北情报）；\n6、安徽政府委员汉奸；\n7、蒋经国上山探查；\n8、叶超死守通路；","涉及时间（19380520）":"19380811","涉及人物":null,"涉及地点":"庐山隘口小路、指挥部位于管理局对面的32号、牯岭部队是工兵连和特务连各一个，其他部队在各登山道路驻守、敌人包围，从小路和无路地方下山、在九莲公路突袭、在通衢要道展示汉奸尸体、九江设立情报站供应赣北情报、交通线偷袭，例如十里铺、炸弹袭击传习学舍前的石桥和芦林房屋、黄龙寺和河西路某某号、庐山难民疏散站位于牯岭，包括沿途庐山垅 隘口 德安设置分站、庐山孤军指挥部驻扎隘口，在东谷山和西谷山一带战斗保持庐山通路","对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'8a4f1333dd38f1b928c419960e940fb44bf4252e949aafd78c3a82163b62146f');
