INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-5d7f59c44314','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',29,'row-29','{"档案来源":"庐山历史纪事3","页数":"73-74","档案原文":null,"档案内容简介":"日军第三大队和庐山守军交战，损失惨重。日本尚未占领隘口，德安/南昌/汉口尚未沦陷。日军放弃右边上头，左翼部队突袭德安；\n日军发动总攻，占领硝瓜船山腰、金轮峰总攻\n​","涉及时间（19380520）":"19380929","涉及人物":"第三大队（机关枪中队全军覆没、队长战死）、第二大队调整为旅团直属部队担任仿制警备；\n联队主力、第二大队","涉及地点":"庐山山麓；硝瓜船山腰、金轮峰、庐山烟山山顶","对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'530475bb744d5e099e7c68b7f4e3e9264d2e767647bd016802ec9b58cd2b3cf9');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-c7ca48c058c8','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',30,'row-30','{"档案来源":"庐山历史纪事3","页数":"74-75","档案原文":null,"档案内容简介":"杨遇春通电全国寻求援助：\n为阵亡烈士送殡（0928 九星高垅游击，破坏电杆电线）；\n游击队总队山上运送给养（庐山四周都有日军、庐山守军不时可以下山截获敌军粮械）","涉及时间（19380520）":"19381021、1030、1117","涉及人物":"杨遇春；\n庐山守军，指导员周南、分队长邱炜雅阵亡；\n政治部主任陈洪时","涉及地点":null,"对应板块":"PART01｜抗日民族统一战线","地图使用情况":null,"后续材料处理":null}'::jsonb,'6509eea41a3dc5b4acf38a801bce8d2d15d3bdc4c5fadc0d91b2caa22613f293');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-62d571ccc446','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',31,'row-31','{"档案来源":"庐山历史纪事3","页数":"77","档案原文":null,"档案内容简介":"多学校上山（途径和目的不知）","涉及时间（19380520）":"1938（具体不知）","涉及人物":"中央政治学校联合大学、北平艺专学校、南昌豫章、葆灵二中学","涉及地点":null,"对应板块":"PART01｜抗日民族统一战线","地图使用情况":null,"后续材料处理":null}'::jsonb,'868faaea2c2177dd2bc5fe731bc7c8189a37a093692b54c66934c2a998dc0116');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-01468639519f','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',32,'row-32','{"档案来源":"庐山历史纪事3","页数":"77-78","档案原文":null,"档案内容简介":"美国教士布朗夫人成立快乐家（庐山儿童乐园/快乐家孤儿院）收养战时弃婴；\n1927年？下山通道只有庐山垅；\n1932年庐山管理局接手，园址定在大林路","涉及时间（19380520）":"1938年秋","涉及人物":"布朗夫人、胡爱德女士、庐山管理局","涉及地点":"大林路","对应板块":"PART01｜抗日民族统一战线","地图使用情况":null,"后续材料处理":null}'::jsonb,'842abb2243d0927e0e9792a199fa26fd1e6247bc042f6e3ac63d0a2ff380329d');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-3ee1dabcb47b','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',33,'row-33','{"档案来源":"庐山历史纪事3","页数":"79-80","档案原文":null,"档案内容简介":"日军进攻庐山：\n0101 修河北岸全线总袭击：1、高垅汪家涧2、金北桥尖山3、东林街张家山4、周家垅\n0112 日军轰炸牯岭\n0116 1、日军袭击罗口隘口北，在庐山垅对峙2、日军两次轰炸牯岭（袭击河西路四一号内地会、英侨葛牧师宅、四四号德侨吴牧师宅、河东路九号圣公会、上中路美以美会、英国学校四周）\n0117日军袭击1、尖山-报国寺2、张家山-五老峰3、观口-庐山垅\n0121日军袭击：株岭阵地、德安围攻庐山\n0125日军袭击：南浔线叶家坂、海会寺-三叠泉、老虎山\n​\n0126杨遇春前往报国寺指挥，向南浔路方面活动\n0128日军袭击牯岭三叠泉阵地；举行一二·八纪念大会\n0131日军轰炸牯岭","涉及时间（19380520）":"193901","涉及人物":null,"涉及地点":null,"对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'c5dfba0577d1a8d505cd0958781ced453c144aca88f81879ac02b6876a63b77a');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-01dcbdfbc978','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',34,'row-34','{"档案来源":"庐山历史纪事3","页数":"81-82","档案原文":null,"档案内容简介":"0205日军轰炸牯岭；世仓部队进攻牯岭西南长脚岭、大凹脑阵地，两小时后向高垅溃逃；后进攻土坝岭阵地，向东林村溃逃；瑞武线日军从小塘山分三路进攻岷山【游击司令钟石磬指挥】\n0206日军全部溃逃\n0207日军斋藤师团一部进攻庐山王家坡阵地；中方游击某部埋伏于彭泽县城附近的周家桥\n0210日军进攻庐山迤西考虎山【英美副领事乘船到达九江】\n0214日军调整防务，疑似有包围岷山和庐山的企图\n0218庐山管理局长甘豫迎接英美舰长，下榻美国学校\n0222日军在修河沿岸上空侦察，北岸张公渡至永修间，运输繁忙，修河北岸较为活跃\n0223牯岭西区划为外侨安全区域\n0226庐山游击队和壮丁队潜往南浔路蓝桥上段，破坏轨道\n0228日军在庐山四周各要径增设铁丝网，埋设地雷炸弹，企图封锁庐山；庐山迄东之花山和高垅日军向牯岭发炮\n​\n​","涉及时间（19380520）":"193902","涉及人物":null,"涉及地点":null,"对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'ef69f755331e624817fcf2ee8ba56f3b6f37c5ff8cb8c26951749730e7012451');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-d487ead3fa38','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',35,'row-35','{"档案来源":"庐山历史纪事3","页数":"82-83","档案原文":null,"档案内容简介":"日军在19370418接受牯岭美国学校","涉及时间（19380520）":"193902","涉及人物":null,"涉及地点":"牯岭美国学校","对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'0513e5ef40f03f21a40cbe49d497e49b783ed2b687bbc48e51c6a57201fc0e28');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-642a9dd12442','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',36,'row-36','{"档案来源":"庐山历史纪事3","页数":"84-85","档案原文":null,"档案内容简介":"0302日军加强庐山封锁；敌机一架在牯岭上空盘旋一小时并散发荒谬传单\n0314九架敌机轰炸牯岭（英侨杜约翰住宅、美国学校、女儿城一带山上）\n0315敌机三架飞牯岭向各山顶投弹（松树路炸死一人）\n0316十八架敌机轰炸牯岭（炸毁日照峰房屋、新路大华饭店、河西路中国银行、小天池房屋、医生凹天主堂、上中路、女儿城山上、仰天坪、土坝岭、火莲院山上、莲谷路）；莲花路-牯岭未逞\n0317五架敌机飞牯岭投弹炸毁房屋；高垅、东林日军向牯岭发炮\n0318牯岭方面日军轰炸，庐山周围的高垅、尖山、东林日军向山上发炮；日军由好汉坡进攻\n​","涉及时间（19380520）":"193903","涉及人物":null,"涉及地点":null,"对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'3a3c3cd2cdf8110968aebd88b2330b0d3d2be924fb21d9236f308a1dc01f4762');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-ca22fe4a4b8b','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',37,'row-37','{"档案来源":"庐山历史纪事3","页数":"85-86","档案原文":null,"档案内容简介":"由南昌及赣北其他方面，抽调大兵攻庐山。共有矶谷大板一〇一等三个师团，配合海陆空的新式武器及化学兵团，分八路，由大寨、莲花峰、好汉坡、月弓堑、土坝岭铁船峰、十里埔、白衣宫等据点进攻；\n日军106师团：13联队队长田中圣道、陆军大尉村治平作、陆军曹长九山启治、陆军曹长谷译盛义、陆军伍长齐藤库作、樱井光男等被击毙；\n日军从南昌、武汉回师，抽调冈吉师团、太久保联队围攻庐山；\n庐山守军环山阻击，三团一大队-莲花洞、龙门沟的佐藤联队，二大队-剪刀峡、土坝岭、锦谷的太久保联队，散打队-铁船峰、碧云庵、报国寺的佐泽联队  十一团四大队-小天池、女儿城的冈吉联队，五大队-三叠泉、五老峰的铃木联队，六大队-筲箕‌洼、仰天坪的山口联队；\n0417守军击毙东林寺的日军联队长；土坝岭下侧守军三大队班长谢某和日军同归于尽","涉及时间（19380520）":"19390415、0417","涉及人物":null,"涉及地点":null,"对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'beddc517751273a65511c7a67be546f549b2680e7cefbb1b8b7bbd99f2253413');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-6e9755c41133','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',38,'row-38','{"档案来源":"庐山历史纪事3","页数":"86-90","档案原文":null,"档案内容简介":"0417 日军一联队从九莲公路和尚坟分四路进攻牯岭，一联队长在土坝岭被击毙；晚间日军进占庐山三北小天池\n详情：\n大赛【怀疑大寨？】、好汉坡、东林寺、大天池、三叠泉、息肩亭各县日军两百到三百不等，向山上进攻；\n我军击退三叠泉、息肩亭日军；\n大寨一线防御工事击毁，推手小天池；\n东林寺日军联队长被击毙，日军炮击土坝岭一带（公坟地区）；\n0418:\n牯岭被日军完全包围，副总指挥部退守山南仰天坪；一大队人掩护、十一团四五两中队驻守太乙村、五老峰，其余部队集合仰天坪。中方预备晚间从张家山、碧云庵突围；\n太乙村的四中队：退路被截断，一部分逃匿在山中，后续爬下山、其余在工事中牺牲；\n五老峰的五中队防地广，各班单独作战（第四班班长顾民被活捉牺牲）；\n十一团宠张家山下山，日军在黄老门车站截击、在张家山口架机枪；\n副总指挥部和三团从碧云庵下山突围（怀疑日军全部在张家山埋伏阻击），向西走：西南方向爬过水田（日军哨所的定位）、渡过水沟、到达前面的小山……到达岷山\n​\n庐山游击小组（青年团）\n日军占领庐山纪念戳、日军设立占领的纪念碑\n​\n​","涉及时间（19380520）":"19390417","涉及人物":null,"涉及地点":null,"对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'43a7a12a67ecdd707d8969201999276bc28350d1f52c5276c14460ee80edbd4b');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-96faee60f9e7','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',39,'row-39','{"档案来源":"庐山历史纪事3","页数":"90-92","档案原文":null,"档案内容简介":"0418 日军冈吉联队从高垄出发，经过王家坡、碧龙潭河谷爬上小天池阵地，月弓堑、剪刀峡、土坝岭防线被击破，庐山牯岭沦陷；\n突围的庐山守军两个团分别在杨遇春、邓子超、胡家位的带领下从碧云庵经报国垄、南浔铁路扎营岷山根据地；\n日军占领庐山传习学舍为军队驻所、庐山图书馆为临时军用仓库（藤堂少将）\n​\n​","涉及时间（19380520）":"19390418","涉及人物":null,"涉及地点":null,"对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'f2afbe5b3355e9517264c456f86e8fd2e0eff25c9d74a38f2c17d39ec6ee4d54');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-0139fd2a5fa5','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',40,'row-40','{"档案来源":"庐山历史纪事3","页数":"92-93","档案原文":null,"档案内容简介":"0421 ：\n庐山游击队突围下山，和岷山游击队一同抗日；\n日军企图围攻岷山，向夏家埠、彭山湖、塔山等进攻。飞机轰炸岷山的秦山和葛洪山等处；\n0501:28年0501庐山成立治安维持会「这个时间可能是纪年」，所在地河东路三十五号","涉及时间（19380520）":"19390421、0501","涉及人物":null,"涉及地点":null,"对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'69f5e94f290d424055c385310444186b34fb5b43502aa634bdfaac8b4782f310');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-b7eb1ce77be2','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',41,'row-41','{"档案来源":"庐山历史纪事3","页数":"93-94","档案原文":null,"档案内容简介":"庐山管理局抵达驻地江西吉安；\n九江沦陷，庐山沦入战区，历经十月，孤军抗战半年；\n庐山管理局行动路径：\n0418和警察队奉杨遇春命令向仰天坪集中、之后随指挥部移驻碧云庵、晚上八时突围下山，一部分当日经过南浔铁路和指挥部进入岷山，另一部分二十日抵达岷山。\n0424奉杨遇春命令随军西撤，经过九江、德安、瑞昌、阳新、武宁等县抵达修水，驻札修水奉。\n0521抵达吉安。\n​","涉及时间（19380520）":"19390417-0421","涉及人物":null,"涉及地点":null,"对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'5f795aebb209d6364bc8cf1835a7b068ae88eb59acf93b2429cdd87c42835aac');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-65e246721e60','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',42,'row-42','{"档案来源":"庐山历史纪事3","页数":"99","档案原文":null,"档案内容简介":"庐山警察队从吉安出发奔赴宁都","涉及时间（19380520）":"19390710","涉及人物":"庐山警察队、庐山警察队队长刘汉东","涉及地点":"吉安、宁都","对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'5cabf71863fd3359169c7f53ef0e776691e71afd2bb2ca2deb6be79772d1d406');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-21be0536418c','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',43,'row-43','{"档案来源":"庐山历史纪事3","页数":"102","档案原文":null,"档案内容简介":"湖北省政府将维持会改组为庐山拱墅筹备处","涉及时间（19380520）":"19400530","涉及人物":"湖北省政府","涉及地点":null,"对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'83bbb8029cfb52a131043d9cb57af1ef1515140cb5c3b1e4f2a9f129c9b6f87e');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-475bafe42e5e','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',44,'row-44','{"档案来源":"庐山历史纪事3","页数":"114-119","档案原文":null,"档案内容简介":"美庐别墅外的日军照片可以使用\n湖北省保安司令部训令：情报搜集计划\n保安教导总队，武昌县金口镇——纸坊——连接五里界之线以北之武昌县内为担任区域；\n保安第一总队，前记之金口镇——纸坊——连接五里界之线(不在其内)以南之武昌县内及武昌，威宁县境与嘉鱼县余家滩连接之线(在内)以北嘉鱼县之一部，为担任区域；\n保安第二总队，大冶——铁山——连接鄂城之线(在内)以东大冶鄂城线之一部，为担任区域；\n铁道保安队，分驻于京汉线，铁道沿线两侧二启罗之地区。","涉及时间（19380520）":"19420224","涉及人物":"湖北省保安司令部","涉及地点":null,"对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'5f30f743407a403b5e664aae80a7358b1372ceb651d8e27877735627d1ecb0b8');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-35e7f6fae4e6','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',45,'row-45','{"档案来源":"庐山历史纪事3","页数":"126/128-129","档案原文":null,"档案内容简介":"庐山特别区公署重新划归江西省政府管理，增加庐山安保自治组织、庐山保甲自卫团；\n庐山特别区公署收到江西省政府批复准予该署迁入原管理局旧址。","涉及时间（19380520）":"194306、19430812","涉及人物":null,"涉及地点":null,"对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'83866ed1dac4319f7f7115815190d5afda51653c3b6e35c3f842aaf1d3da896e');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-16f929439720','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',46,'row-46','{"档案来源":"庐山历史纪事3","页数":"130-131","档案原文":null,"档案内容简介":"李锦枝带领的游击队（悍匪）袭击庐山警察局莲谷路分驻所，窝藏在牯岭东方八里许的修静庵一带","涉及时间（19380520）":"19431003","涉及人物":null,"涉及地点":"修静庵一带、庐山警察局莲谷路分驻所","对应板块":"PART02｜战争","地图使用情况":null,"后续材料处理":null}'::jsonb,'e9df6ad5cb96289fcbda2ab17b3aa261718bb1d5b56e679dd00841d06e23278f');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-b08629f9fb6d','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',47,'row-47','{"档案来源":"庐山历史纪事3","页数":"139-141","档案原文":null,"档案内容简介":"19440817\n援华抗日的美14航空队-飞虎队一架轰炸机被击中，机组人员跳伞至庐山西麓金桥村孔家山一带得到援助。\n涉及到：星子县流亡政府领导抗日返敌行动二中队、山南庐山垅垄中大队、流亡政府所在地杨家山（考证流亡政府？）\n0826:庐山垅山路-汉阳峰-项家\n0827:项家-观音桥-神灵湖渡口\n0829:抵达都昌陈浪，到达杨家山\n0901：护送至乐平-余江-赣州-桂林\n日伪军报复，扫荡金桥村、庐山垅、神灵湖","涉及时间（19380520）":"194408-09","涉及人物":null,"涉及地点":null,"对应板块":"PART3｜战后","地图使用情况":null,"后续材料处理":null}'::jsonb,'d70310b80ea5bdb052b86062a8c38bc34fbbeb79dd783473ecfcb50edf1e5f75');
INSERT INTO public.raw_import_records (id,batch_key,source_file,source_type,sheet_name,row_index,row_key,payload,payload_hash) VALUES ('raw-70a6d0896e17','lushan-platform-2026-07','庐山历史归档_Table1_Default View.xlsx','xlsx','Table1_Default View',48,'row-48','{"档案来源":"庐山历史纪事3","页数":"146-156","档案原文":null,"档案内容简介":"庐山战后的工作恢复：\n0130 警察局\n1001庐山管理局\n1006管理局返回庐山\n1027全部到达牯岭，正式接管（重新划定管辖区域\n简单描述日军占领的情况（有照片）\n接受庐山图书馆\n1031划定警备区","涉及时间（19380520）":"1945","涉及人物":null,"涉及地点":null,"对应板块":"PART3｜战后","地图使用情况":null,"后续材料处理":null}'::jsonb,'8c4d061a3cfa53f6e0fd0013aa6674ab495601c50878a91dc4be34ed0f3c17fe');
