INSERT INTO public.events (id,title,slug,event_type,event_domain,event_subtype,actor_side,initiator_side,start_time_raw,end_time_raw,normalized_start,normalized_end,start_date,end_date,date_precision,year,month,day,summary,description,narrative,classification_note,region,region_id,place_id,importance,source_confidence,tags,status) VALUES ('ev-b2190e15f6ca','由南昌及赣北其他方面，抽调大兵攻庐山','ev-b2190e15f6ca','historical','war','attack','mixed',NULL,'19390415、0417',NULL,'1939-04-15','1939-04-15','1939-04-15','1939-04-15','day',1939,4,15,'由南昌及赣北其他方面，抽调大兵攻庐山','由南昌及赣北其他方面，抽调大兵攻庐山。共有矶谷大板一〇一等三个师团，配合海陆空的新式武器及化学兵团，分八路，由大寨、莲花峰、好汉坡、月弓堑、土坝岭铁船峰、十里埔、白衣宫等据点进攻； 日军106师团：13联队队长田中圣道、陆军大尉村治平作、陆军曹长九山启治、陆军曹长谷译盛义、陆军伍长齐藤库作、樱井光男等被击毙； 日军从南昌、武汉回师，抽调冈吉师团、太久保联队围攻庐山； 庐山守军环山阻击，三团一大队-莲花洞、龙门沟的佐藤联队，二大队-剪刀峡、土坝岭、锦谷的太久保联队，散打队-铁船峰、碧云庵、报国寺的佐泽联队 十一团四大队-小天池、女儿城的冈吉联队，五大队-三叠泉、五老峰的铃木联队，六大队-筲箕‌洼、仰天坪的山口联队； 0417守军击毙东林寺的日军联队长；土坝岭下侧守军三大队班长谢某和日军同归于尽','由南昌及赣北其他方面，抽调大兵攻庐山。共有矶谷大板一〇一等三个师团，配合海陆空的新式武器及化学兵团，分八路，由大寨、莲花峰、好汉坡、月弓堑、土坝岭铁船峰、十里埔、白衣宫等据点进攻； 日军106师团：13联队队长田中圣道、陆军大尉村治平作、陆军曹长九山启治、陆军曹长谷译盛义、陆军伍长齐藤库作、樱井光男等被击毙； 日军从南昌、武汉回师，抽调冈吉师团、太久保联队围攻庐山； 庐山守军环山阻击，三团一大队-莲花洞、龙门沟的佐藤联队，二大队-剪刀峡、土坝岭、锦谷的太久保联队，散打队-铁船峰、碧云庵、报国寺的佐泽联队 十一团四大队-小天池、女儿城的冈吉联队，五大队-三叠泉、五老峰的铃木联队，六大队-筲箕‌洼、仰天坪的山口联队； 0417守军击毙东林寺的日军联队长；土坝岭下侧守军三大队班长谢某和日军同归于尽','按关键词、动作发起方与原文主语自动初分；mixed 仅用于多方同场或主次难判记录。','庐山牯岭及周边','region-guling',NULL,3,'raw_import','["war","attack","mixed","archive_xlsx"]','active');
INSERT INTO public.events (id,title,slug,event_type,event_domain,event_subtype,actor_side,initiator_side,start_time_raw,end_time_raw,normalized_start,normalized_end,start_date,end_date,date_precision,year,month,day,summary,description,narrative,classification_note,region,region_id,place_id,importance,source_confidence,tags,status) VALUES ('ev-15cf13f6ef9b','0417 日军一联队从九莲公路和尚坟分四路进攻牯岭，一联队长在土坝岭被击毙；晚间日军进占庐山三北小天池 详情： 大赛【怀疑大寨？】、好汉坡、东林寺、大天池、三叠','ev-15cf13f6ef9b','historical','war','occupation','japanese_army','japanese_army','19390417',NULL,'1939-04-17','1939-04-17','1939-04-17','1939-04-17','day',1939,4,17,'0417 日军一联队从九莲公路和尚坟分四路进攻牯岭，一联队长在土坝岭被击毙；晚间日军进占庐山三北小天池 详情： 大赛【怀疑大寨？】、好汉坡、东林寺、大天池、三叠','0417 日军一联队从九莲公路和尚坟分四路进攻牯岭，一联队长在土坝岭被击毙；晚间日军进占庐山三北小天池 详情： 大赛【怀疑大寨？】、好汉坡、东林寺、大天池、三叠泉、息肩亭各县日军两百到三百不等，向山上进攻； 我军击退三叠泉、息肩亭日军； 大寨一线防御工事击毁，推手小天池； 东林寺日军联队长被击毙，日军炮击土坝岭一带（公坟地区）； 0418: 牯岭被日军完全包围，副总指挥部退守山南仰天坪；一大队人掩护、十一团四五两中队驻守太乙村、五老峰，其余部队集合仰天坪。中方预备晚间从张家山、碧云庵突围； 太乙村的四中队：退路被截断，一部分逃匿在山中，后续爬下山、其余在工事中牺牲； 五老峰的五中队防地广，各班单独作战（第四班班长顾民被活捉牺牲）； 十一团宠张家山下山，日军在黄老门车站截击、在张家山口架机枪； 副总指挥部和三团从碧云庵下山突围（怀疑日军全部在张家山埋伏阻击），向西走：西南方向爬过水田（日军哨所的定位）、渡过水沟、到达前面的小山……到达岷山 庐山游击小组（青年团） 日军占领庐山纪念戳、日军设立占领的纪念碑','0417 日军一联队从九莲公路和尚坟分四路进攻牯岭，一联队长在土坝岭被击毙；晚间日军进占庐山三北小天池 详情： 大赛【怀疑大寨？】、好汉坡、东林寺、大天池、三叠泉、息肩亭各县日军两百到三百不等，向山上进攻； 我军击退三叠泉、息肩亭日军； 大寨一线防御工事击毁，推手小天池； 东林寺日军联队长被击毙，日军炮击土坝岭一带（公坟地区）； 0418: 牯岭被日军完全包围，副总指挥部退守山南仰天坪；一大队人掩护、十一团四五两中队驻守太乙村、五老峰，其余部队集合仰天坪。中方预备晚间从张家山、碧云庵突围； 太乙村的四中队：退路被截断，一部分逃匿在山中，后续爬下山、其余在工事中牺牲； 五老峰的五中队防地广，各班单独作战（第四班班长顾民被活捉牺牲）； 十一团宠张家山下山，日军在黄老门车站截击、在张家山口架机枪； 副总指挥部和三团从碧云庵下山突围（怀疑日军全部在张家山埋伏阻击），向西走：西南方向爬过水田（日军哨所的定位）、渡过水沟、到达前面的小山……到达岷山 庐山游击小组（青年团） 日军占领庐山纪念戳、日军设立占领的纪念碑','按关键词、动作发起方与原文主语自动初分；mixed 仅用于多方同场或主次难判记录。','庐山牯岭及周边','region-guling',NULL,3,'raw_import','["war","occupation","japanese_army","archive_xlsx"]','active');
