INSERT INTO public.events (id,title,slug,event_type,event_domain,event_subtype,actor_side,initiator_side,start_time_raw,end_time_raw,normalized_start,normalized_end,start_date,end_date,date_precision,year,month,day,summary,description,narrative,classification_note,region,region_id,place_id,importance,source_confidence,tags,status) VALUES ('ev-ad1ce8f67648','0421 ： 庐山游击队突围下山，和岷山游击队一同抗日； 日军企图围攻岷山，向夏家埠、彭山湖、塔山等进攻','ev-ad1ce8f67648','historical','war','bombing','chinese_forces','chinese_forces','19390421、0501',NULL,'1939-04-21','1939-04-21','1939-04-21','1939-04-21','day',1939,4,21,'0421 ： 庐山游击队突围下山，和岷山游击队一同抗日； 日军企图围攻岷山，向夏家埠、彭山湖、塔山等进攻','0421 ： 庐山游击队突围下山，和岷山游击队一同抗日； 日军企图围攻岷山，向夏家埠、彭山湖、塔山等进攻。飞机轰炸岷山的秦山和葛洪山等处； 0501:28年0501庐山成立治安维持会「这个时间可能是纪年」，所在地河东路三十五号','0421 ： 庐山游击队突围下山，和岷山游击队一同抗日； 日军企图围攻岷山，向夏家埠、彭山湖、塔山等进攻。飞机轰炸岷山的秦山和葛洪山等处； 0501:28年0501庐山成立治安维持会「这个时间可能是纪年」，所在地河东路三十五号','按关键词、动作发起方与原文主语自动初分；mixed 仅用于多方同场或主次难判记录。','庐山牯岭及周边','region-guling',NULL,3,'raw_import','["war","bombing","chinese_forces","archive_xlsx"]','active');
INSERT INTO public.events (id,title,slug,event_type,event_domain,event_subtype,actor_side,initiator_side,start_time_raw,end_time_raw,normalized_start,normalized_end,start_date,end_date,date_precision,year,month,day,summary,description,narrative,classification_note,region,region_id,place_id,importance,source_confidence,tags,status) VALUES ('ev-15aef1964c67','庐山管理局抵达驻地江西吉安； 九江沦陷，庐山沦入战区，历经十月，孤军抗战半年； 庐山管理局行动路径： 0418和警察队奉杨遇春命令向仰天坪集中、之后随指挥部移驻','ev-15aef1964c67','historical','war','occupation','chinese_forces',NULL,'19390417-0421',NULL,'1939-04-17','1939-04-17','1939-04-17','1939-04-17','day',1939,4,17,'庐山管理局抵达驻地江西吉安； 九江沦陷，庐山沦入战区，历经十月，孤军抗战半年； 庐山管理局行动路径： 0418和警察队奉杨遇春命令向仰天坪集中、之后随指挥部移驻','庐山管理局抵达驻地江西吉安； 九江沦陷，庐山沦入战区，历经十月，孤军抗战半年； 庐山管理局行动路径： 0418和警察队奉杨遇春命令向仰天坪集中、之后随指挥部移驻碧云庵、晚上八时突围下山，一部分当日经过南浔铁路和指挥部进入岷山，另一部分二十日抵达岷山。 0424奉杨遇春命令随军西撤，经过九江、德安、瑞昌、阳新、武宁等县抵达修水，驻札修水奉。 0521抵达吉安。','庐山管理局抵达驻地江西吉安； 九江沦陷，庐山沦入战区，历经十月，孤军抗战半年； 庐山管理局行动路径： 0418和警察队奉杨遇春命令向仰天坪集中、之后随指挥部移驻碧云庵、晚上八时突围下山，一部分当日经过南浔铁路和指挥部进入岷山，另一部分二十日抵达岷山。 0424奉杨遇春命令随军西撤，经过九江、德安、瑞昌、阳新、武宁等县抵达修水，驻札修水奉。 0521抵达吉安。','按关键词、动作发起方与原文主语自动初分；mixed 仅用于多方同场或主次难判记录。','庐山牯岭及周边','region-guling',NULL,3,'raw_import','["war","occupation","chinese_forces","archive_xlsx"]','active');
INSERT INTO public.events (id,title,slug,event_type,event_domain,event_subtype,actor_side,initiator_side,start_time_raw,end_time_raw,normalized_start,normalized_end,start_date,end_date,date_precision,year,month,day,summary,description,narrative,classification_note,region,region_id,place_id,importance,source_confidence,tags,status) VALUES ('ev-0acaac3abb8f','美庐别墅外的日军照片可以使用 湖北省保安司令部训令：情报搜集计划 保安教导总队，武昌县金口镇——纸坊——连接五里界之线以北之武昌县内为担任区域； 保安第一总队，','ev-0acaac3abb8f','historical','war','attack','mixed',NULL,'19420224',NULL,'1942-02-24','1942-02-24','1942-02-24','1942-02-24','day',1942,2,24,'美庐别墅外的日军照片可以使用 湖北省保安司令部训令：情报搜集计划 保安教导总队，武昌县金口镇——纸坊——连接五里界之线以北之武昌县内为担任区域； 保安第一总队，','美庐别墅外的日军照片可以使用 湖北省保安司令部训令：情报搜集计划 保安教导总队，武昌县金口镇——纸坊——连接五里界之线以北之武昌县内为担任区域； 保安第一总队，前记之金口镇——纸坊——连接五里界之线(不在其内)以南之武昌县内及武昌，威宁县境与嘉鱼县余家滩连接之线(在内)以北嘉鱼县之一部，为担任区域； 保安第二总队，大冶——铁山——连接鄂城之线(在内)以东大冶鄂城线之一部，为担任区域； 铁道保安队，分驻于京汉线，铁道沿线两侧二启罗之地区。','美庐别墅外的日军照片可以使用 湖北省保安司令部训令：情报搜集计划 保安教导总队，武昌县金口镇——纸坊——连接五里界之线以北之武昌县内为担任区域； 保安第一总队，前记之金口镇——纸坊——连接五里界之线(不在其内)以南之武昌县内及武昌，威宁县境与嘉鱼县余家滩连接之线(在内)以北嘉鱼县之一部，为担任区域； 保安第二总队，大冶——铁山——连接鄂城之线(在内)以东大冶鄂城线之一部，为担任区域； 铁道保安队，分驻于京汉线，铁道沿线两侧二启罗之地区。','按关键词、动作发起方与原文主语自动初分；mixed 仅用于多方同场或主次难判记录。','庐山牯岭及周边','region-guling',NULL,3,'raw_import','["war","attack","mixed","archive_xlsx"]','active');
