INSERT INTO public.timeline_entries (time_key,start_date,end_date,date_precision,sort_order,chapter_no,chapter_title,title,narration,scope,map_focus,source_context) VALUES ('19390205-093','1939-02-05','1939-02-05','day',93,4,'第四幕：孤峰傲骨，游击旌旗（1938年10月—1945年4月）','向牯岭西南长脚岭、大凹脑阵地攻击，失败后向高垅溃窜','向牯岭西南长脚岭、大凹脑阵地攻击，失败后向高垅溃窜。旋复向我土坝岭阵地猛袭，失败后向东林村方面溃退。英美驻汉领事馆通知牯岭外侨撤退。同时向日方交涉展缓限期。瑞武线之敌由小塘山分三路再度围攻岷山，至正午十二时，与我发生激战，游击司令钟石磐亲临指挥⑥','lushan','{}'::jsonb,'庐山抗战历史事件表（批注地点坐标）.docx row 93');
