INSERT INTO public.timeline_entries (time_key,start_date,end_date,date_precision,sort_order,chapter_no,chapter_title,title,narration,scope,map_focus,source_context) VALUES ('19390207-095','1939-02-07','1939-02-07','day',95,4,'第四幕：孤峰傲骨，游击旌旗（1938年10月—1945年4月）','日军斋藤师团之一部进攻王家坡阵地，失败','日军斋藤师团之一部进攻王家坡阵地，失败。 我游击某部，埋伏于彭泽县城附近之周家桥，遇敌五十人经过，伏兵四出，敌狼狈溃窜，被我击毙多名。省新闻界慰劳游击部队，特发起游艺募捐三天，各界人士参加，极为踊跃。⑥','lushan','{}'::jsonb,'庐山抗战历史事件表（批注地点坐标）.docx row 95');
