INSERT INTO public.timeline_entries (time_key,start_date,end_date,date_precision,sort_order,chapter_no,chapter_title,title,narration,scope,map_focus,source_context) VALUES ('19390415-118','1939-04-15','1939-04-17','range',118,4,'第四幕：孤峰傲骨，游击旌旗（1938年10月—1945年4月）','日军从南昌、武汉抽调矶谷大阪101等三个师团/冈吉106师团、太久保联队，分大寨、莲花峰、好汉坡、月弓堑、土坝岭、铁船峰、十里铺、白衣宫八路进攻庐山','日军从南昌、武汉抽调矶谷大阪101等三个师团⑥/冈吉106师团、太久保联队，分大寨、莲花峰、好汉坡、月弓堑、土坝岭、铁船峰、十里铺、白衣宫八路进攻庐山。守军三团一大队对付从莲花洞、龙门沟上来的佐藤联队；二大队对付从剪刀峡、土坝岭、锦谷上来的太久保联队；三大队对付从铁船峰、碧云庵、报国寺上来的佐泽联队。十一团四大队对付从小天池、女儿城进犯的冈吉联队；五大队对付从三叠泉、五老峰进犯的铃木联队；六大队对付从筲箕洼、仰天坪进犯的山口联队。⑯','lushan','{}'::jsonb,'庐山抗战历史事件表（批注地点坐标）.docx row 118');
INSERT INTO public.timeline_entries (time_key,start_date,end_date,date_precision,sort_order,chapter_no,chapter_title,title,narration,scope,map_focus,source_context) VALUES ('19390417-119','1939-04-17','1939-04-17','day',119,4,'第四幕：孤峰傲骨，游击旌旗（1938年10月—1945年4月）','日军从大寨、好汉坡、东林寺、大天池、三叠泉、息肩亭各线围攻','日军从大寨、好汉坡、东林寺、大天池、三叠泉、息肩亭各线围攻。 日军一联队从九莲公路和尚坟（东林寺附近）分四路进攻牯岭，联队长在土坝岭被击毙，晚占领小天池。一部日军在汉奸引路下从莲花洞小路向牯岭攻击⑥','lushan','{}'::jsonb,'庐山抗战历史事件表（批注地点坐标）.docx row 119');
INSERT INTO public.timeline_entries (time_key,start_date,end_date,date_precision,sort_order,chapter_no,chapter_title,title,narration,scope,map_focus,source_context) VALUES ('19390418-120','1939-04-18','1939-04-20','range',120,4,'第四幕：孤峰傲骨，游击旌旗（1938年10月—1945年4月）','牯岭被完全包围，副总指挥部退守仰天坪，余部困守太乙村、五老峰，多牺牲','牯岭被完全包围，副总指挥部退守仰天坪，余部困守太乙村、五老峰，多牺牲。在汉奸引路下的一部日军从王家坡、碧龙潭登上小天池阵地，进而攻入牯岭，月弓堑、剪刀峡、土坝岭防线也被攻破，庐山沦陷。⑥ 游击队副总指挥部三团、警察局突围下山，从碧云庵经报国垄、越南浔铁路于20日夜进入岷山，十一团从张家山下山。⑥','lushan','{}'::jsonb,'庐山抗战历史事件表（批注地点坐标）.docx row 120');
