INSERT INTO public.timeline_keyframes (id,title,year,month,day,place_id,event_id,camera,description,sort_order,status) VALUES ('kf-da51c6bb58dd','向牯岭西南长脚岭、大凹脑阵地攻击，失败后向高垅溃窜',1939,2,5,NULL,'ev-347f8665d370','{}','向牯岭西南长脚岭、大凹脑阵地攻击，失败后向高垅溃窜。旋复向我土坝岭阵地猛袭，失败后向东林村方面溃退。英美驻汉领事馆通知牯岭外侨撤退。同时向日方交涉展缓限期。瑞武线之敌由小塘山分三路再度围攻岷山，至正午十二时，与我发生激战，游击司令钟石磐亲临指挥⑥',81,'active');
INSERT INTO public.timeline_keyframes (id,title,year,month,day,place_id,event_id,camera,description,sort_order,status) VALUES ('kf-21e2ddad400a','围攻岷山日军撤退，死伤二百余人',1939,2,6,NULL,'ev-d1f06d27ca85','{}','围攻岷山日军撤退，死伤二百余人。钟司令右臂负伤。⑥',82,'active');
INSERT INTO public.timeline_keyframes (id,title,year,month,day,place_id,event_id,camera,description,sort_order,status) VALUES ('kf-c7f5cbd7ab99','日军斋藤师团之一部进攻王家坡阵地，失败',1939,2,7,NULL,'ev-b046dd840d76','{}','日军斋藤师团之一部进攻王家坡阵地，失败。 我游击某部，埋伏于彭泽县城附近之周家桥，遇敌五十人经过，伏兵四出，敌狼狈溃窜，被我击毙多名。省新闻界慰劳游击部队，特发起游艺募捐三天，各界人士参加，极为踊跃。⑥',83,'active');
INSERT INTO public.timeline_keyframes (id,title,year,month,day,place_id,event_id,camera,description,sort_order,status) VALUES ('kf-2b18b969bc8b','牯岭各国侨民再度开会，决定不愿离山',1939,2,8,NULL,'ev-86969914e347','{}','牯岭各国侨民再度开会，决定不愿离山。⑥',84,'active');
